<?php
/** Read-only Automation Runs admin page. @package AIContentStudio */
if(!defined('ABSPATH')){exit;}
final class AICS_Automation_Runs_Page{
	private const SLUG='aics-automation-runs';private const PER_PAGE=20;
	public static function register():void{add_action('admin_post_aics_control_automation_run',array(__CLASS__,'handle_control'));add_action('admin_notices',array(__CLASS__,'notice'));add_action('admin_footer',array(__CLASS__,'render_controls'));}
	public static function handle_control():void{if(!current_user_can(\AIContentStudio\Core\Permissions::manage())){wp_die(esc_html__('You do not have permission to perform this action.','ai-content-studio'),'',array('response'=>403));}$id=absint($_POST['run_id']??0);$action=sanitize_key(wp_unslash($_POST['run_control_action']??''));if(!$id||!in_array($action,array('retry','resume','cancel'),true)){self::redirect($id,'invalid_action');}check_admin_referer('aics_control_run_'.$id.'_'.$action,'aics_run_control_nonce');if('cancel'===$action&&'1'!==(string)($_POST['cancellation_acknowledgement']??'')){self::redirect($id,'cancel_acknowledgement_required');}$expected=array('status'=>sanitize_key(wp_unslash($_POST['expected_status']??'')),'step'=>sanitize_key(wp_unslash($_POST['expected_step']??'')),'updated_at'=>sanitize_text_field(wp_unslash($_POST['expected_updated_at']??'')));$result=(new AICS_Automation_Run_Control_Service())->execute($id,$action,get_current_user_id(),$expected);self::redirect($id,is_wp_error($result)?$result->get_error_code():$result['code']);}
	public static function notice():void{if(self::SLUG!==(isset($_GET['page'])?sanitize_key(wp_unslash($_GET['page'])):'')||empty($_GET['aics_run_notice'])){return;}$code=sanitize_key(wp_unslash($_GET['aics_run_notice']));$map=array('run_retry_queued'=>'Retry was queued for normal worker processing.','run_resumed'=>'The run was safely resumed and queued.','run_cancelled'=>'The run was cancelled. Existing WordPress posts were not changed.','run_state_changed'=>'The run changed after this page was loaded. Refresh the page and review its current state.','run_lock_active'=>'This run is currently being processed. Review it again after the current worker operation finishes.','another_profile_run_active'=>'Another automation cycle is already active for this profile.','cancel_acknowledgement_required'=>'Confirm that existing WordPress posts will not be changed.','approval_still_pending'=>'Required approval is still pending.','non_retryable_error'=>'This error requires manual review and cannot be retried safely.','ownership_conflict'=>'WordPress post ownership could not be verified.','missing_run_configuration'=>'The saved run configuration cannot be reconstructed safely.','action_audit_failed'=>'The action was not applied because its audit record could not be saved.','invalid_action'=>'The requested run action is invalid.','retry_not_allowed'=>'Retry is not available for this run.','resume_not_allowed'=>'Resume is not available for this run.','cancel_not_allowed'=>'Cancel is not available for this run.','run_is_terminal'=>'This run is already complete or cancelled.');if(!isset($map[$code])){return;}$success=in_array($code,array('run_retry_queued','run_resumed','run_cancelled'),true);?><div class="notice <?php echo $success?'notice-success':'notice-error';?> is-dismissible"><p><?php echo esc_html__($map[$code],'ai-content-studio');?></p></div><?php }
	public static function render_controls():void{if(!current_user_can(\AIContentStudio\Core\Permissions::manage())||self::SLUG!==(isset($_GET['page'])?sanitize_key(wp_unslash($_GET['page'])):'')||'details'!==(isset($_GET['view'])?sanitize_key(wp_unslash($_GET['view'])):'')){return;}$data=(new AICS_Automation_Run_Inspector())->inspect(absint($_GET['run_id']??0));if(empty($data['success'])){return;}$controls=$data['controls'];$available=array_filter(array($controls['retry'],$controls['resume'],$controls['cancel']),static fn($p)=>!empty($p['allowed']));if($available):?><section class="aics-card aics-run-controls"><div class="aics-card-header"><h2><?php esc_html_e('Run Controls','ai-content-studio');?></h2></div><div class="aics-card-body"><p><?php esc_html_e('These controls only change persistent run state. Processing continues later through the normal background worker.','ai-content-studio');?></p><?php foreach($available as $plan):self::control_form($data['run'],$plan,!empty($controls['has_posts']));endforeach;?></div></section><?php else:?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Run Controls','ai-content-studio');?></h2></div><div class="aics-card-body"><p><?php echo esc_html(self::eligibility_message($controls));?></p></div></section><?php endif;self::history($data['action_history']);}
	private static function control_form(array $run,array $plan,bool $has_posts):void{$action=$plan['action'];$labels=array('retry'=>'Retry Now','resume'=>'Resume Run','cancel'=>'Cancel Run');?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="aics-run-control-form"><input type="hidden" name="action" value="aics_control_automation_run"><input type="hidden" name="run_id" value="<?php echo esc_attr($run['id']);?>"><input type="hidden" name="run_control_action" value="<?php echo esc_attr($action);?>"><input type="hidden" name="expected_status" value="<?php echo esc_attr($run['status']);?>"><input type="hidden" name="expected_step" value="<?php echo esc_attr($run['current_step']);?>"><input type="hidden" name="expected_updated_at" value="<?php echo esc_attr($run['updated_at']);?>"><?php wp_nonce_field('aics_control_run_'.$run['id'].'_'.$action,'aics_run_control_nonce');if('cancel'===$action):?><p><strong><?php esc_html_e('Cancelling this run stops further AI Content Studio processing. Existing WordPress drafts, scheduled posts and published posts are not changed.','ai-content-studio');?></strong></p><label><input type="checkbox" name="cancellation_acknowledgement" value="1" required> <?php esc_html_e('I understand that existing WordPress posts will not be changed.','ai-content-studio');?></label><?php endif;?><p><button type="submit" class="button <?php echo in_array($action,array('retry','resume'),true)?'button-primary':'';?>"><?php echo esc_html__($labels[$action],'ai-content-studio');?></button></p></form><?php }
	private static function history(array $rows):void{?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Administrator Actions','ai-content-studio');?></h2></div><div class="aics-card-body aics-table-wrap"><?php if(!$rows):?><p><?php esc_html_e('No administrator actions have been recorded for this run.','ai-content-studio');?></p><?php else:?><table class="widefat striped"><thead><tr><th><?php esc_html_e('Action','ai-content-studio');?></th><th><?php esc_html_e('Previous State','ai-content-studio');?></th><th><?php esc_html_e('Resulting State','ai-content-studio');?></th><th><?php esc_html_e('Administrator','ai-content-studio');?></th><th><?php esc_html_e('Reason','ai-content-studio');?></th><th><?php esc_html_e('Date','ai-content-studio');?></th></tr></thead><tbody><?php foreach($rows as $row):$user=get_userdata(absint($row['actor_user_id']));?><tr><td><?php echo esc_html(array('retry'=>'Retry Requested','resume'=>'Run Resumed','cancel'=>'Run Cancelled')[$row['action_type']]??'Administrator Action');?></td><td><?php echo esc_html($row['previous_status'].' / '.$row['previous_step'].' ('.$row['previous_attempt_count'].')');?></td><td><?php echo esc_html($row['resulting_status'].' / '.$row['resulting_step'].' ('.$row['resulting_attempt_count'].')');?></td><td><?php echo esc_html($user instanceof WP_User?$user->display_name:__('Deleted User','ai-content-studio'));?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',(string)$row['reason_code'])));?></td><td><?php echo esc_html(self::date($row['created_at']));?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php }
	private static function eligibility_message(array $controls):string{if(!empty($controls['lock_blocks'])){return __('This run is currently being processed. Review it again after the current worker operation finishes.','ai-content-studio');}$codes=array_column(array($controls['retry'],$controls['resume'],$controls['cancel']),'reason_code');if(in_array('run_is_terminal',$codes,true)){return __('This run is complete or cancelled.','ai-content-studio');}if(in_array('approval_still_pending',$codes,true)){return __('Required approval is still pending.','ai-content-studio');}return __('No safe recovery action is available. Review the run details and error information.','ai-content-studio');}
	private static function redirect(int $id,string $notice):void{$url=self::url(array('view'=>'details','run_id'=>$id,'aics_run_notice'=>sanitize_key($notice)));wp_safe_redirect($url);exit;}
	public static function render():void{if(!current_user_can(\AIContentStudio\Core\Permissions::manage())){wp_die(esc_html__('You do not have permission to access this page.','ai-content-studio'));}$inspector=new AICS_Automation_Run_Inspector();$view=isset($_GET['view'])?sanitize_key(wp_unslash($_GET['view'])):'';?><div class="wrap aics-admin-wrap aics-runs-page"><header class="aics-page-header"><h1 class="aics-page-title"><?php esc_html_e('Automation Runs','ai-content-studio');?></h1><p class="aics-page-description"><?php esc_html_e('Read-only operational history for automated content cycles.','ai-content-studio');?></p></header><?php 'details'===$view?self::details($inspector):self::listing($inspector);?></div><?php }
	private static function listing(AICS_Automation_Run_Inspector $i):void{$counts=$i->counts();$run_view=isset($_GET['run_view'])?sanitize_key(wp_unslash($_GET['run_view'])):'all';$run_view=in_array($run_view,array('all','needs_attention'),true)?$run_view:'all';$status=self::allowed('status',array('queued','running','retrying','completed','failed','cancelled'));$step=self::allowed('step',array('pending','generate_ideas','evaluate_ideas','select_ideas','queue_idea','generate_article','validate_article','create_post','schedule_post','publish_post','waiting_idea_approval','waiting_article_approval','waiting_publish_approval','finalize','complete'));$trigger=self::allowed('trigger',array('scheduled','manual','retry','system'));$profile=absint($_GET['profile_id']??0);$range=self::allowed('date_range',array('7','30','90'));$paged=max(1,absint($_GET['paged']??1));$args=array('limit'=>self::PER_PAGE,'offset'=>($paged-1)*self::PER_PAGE,'orderby'=>'updated_at','order'=>'DESC');if($status){$args['status']=$status;}if($step){$args['current_step']=$step;}if($trigger){$args['trigger_type']=$trigger;}if($profile){$args['profile_id']=$profile;}if($range){$args['created_after']=gmdate('Y-m-d H:i:s',time()-DAY_IN_SECONDS*(int)$range);}if('needs_attention'===$run_view){$args['needs_attention']=true;}$total=(new AICS_Automation_Run_Repository())->count_runs($args);$rows=$i->list_runs($args);$profiles=(new AICS_Automation_Profile_Repository())->get_profiles(array('limit'=>100));self::cards($counts);?><nav class="nav-tab-wrapper aics-approval-tabs" aria-label="<?php esc_attr_e('Automation run views','ai-content-studio');?>"><a class="nav-tab <?php echo 'all'===$run_view?'nav-tab-active':'';?>" href="<?php echo esc_url(self::url(array('run_view'=>'all')));?>"><?php esc_html_e('All Runs','ai-content-studio');?></a><a class="nav-tab <?php echo 'needs_attention'===$run_view?'nav-tab-active':'';?>" href="<?php echo esc_url(self::url(array('run_view'=>'needs_attention')));?>"><?php esc_html_e('Needs Attention','ai-content-studio');?> (<?php echo esc_html(number_format_i18n($counts['needs_attention']));?>)</a></nav><?php self::filters($run_view,$status,$step,$trigger,$profile,$range,$profiles);if(!$rows){?><div class="aics-empty-state"><h2><?php esc_html_e('No automation runs found','ai-content-studio');?></h2><p><?php esc_html_e('No runs match the selected view and filters.','ai-content-studio');?></p></div><?php return;}?><div class="aics-table-wrap"><table class="widefat striped aics-runs-table"><thead><tr><th><?php esc_html_e('Run','ai-content-studio');?></th><th><?php esc_html_e('Automation','ai-content-studio');?></th><th><?php esc_html_e('Trigger','ai-content-studio');?></th><th><?php esc_html_e('Status','ai-content-studio');?></th><th><?php esc_html_e('Current Step','ai-content-studio');?></th><th><?php esc_html_e('Content','ai-content-studio');?></th><th><?php esc_html_e('Started','ai-content-studio');?></th><th><?php esc_html_e('Completed','ai-content-studio');?></th><th><?php esc_html_e('Last Error','ai-content-studio');?></th><th><?php esc_html_e('Action','ai-content-studio');?></th></tr></thead><tbody><?php foreach($rows as $row):$r=$row['run'];?><tr><td><strong>#<?php echo esc_html($r['id']);?></strong><br><code><?php echo esc_html(substr($r['run_uuid'],0,8));?>…</code></td><td><?php echo esc_html($row['profile_name']);?></td><td><?php echo esc_html($i->trigger_label($r['trigger_type']));?></td><td><span class="aics-status-badge aics-status--<?php echo esc_attr($r['status']);?>"><?php echo esc_html($i->status_label($r['status']));?></span></td><td><?php echo esc_html($i->step_label($r['current_step']));?></td><td><?php echo esc_html(sprintf(__('%1$d ideas · %2$d articles · %3$d posts','ai-content-studio'),$row['ideas'],$row['articles'],$row['posts']));?></td><td><?php echo esc_html(self::date($r['started_at']?:$r['created_at']));?></td><td><?php echo esc_html(self::date($r['completed_at']));?></td><td><?php echo esc_html($i->error_label($r['last_error_code']));?></td><td><a class="button" aria-label="<?php echo esc_attr(sprintf(__('View details for run %d','ai-content-studio'),$r['id']));?>" href="<?php echo esc_url(self::url(array('view'=>'details','run_id'=>$r['id'])));?>"><?php esc_html_e('View Details','ai-content-studio');?></a></td></tr><?php endforeach;?></tbody></table></div><?php self::pagination($total,$paged);}
	private static function details(AICS_Automation_Run_Inspector $i):void{$data=$i->inspect(absint($_GET['run_id']??0));if(empty($data['success'])){?><div class="notice notice-error"><p><?php esc_html_e('The requested automation run was not found.','ai-content-studio');?></p></div><p><a href="<?php echo esc_url(self::url());?>"><?php esc_html_e('Back to Automation Runs','ai-content-studio');?></a></p><?php return;}$r=$data['run'];$c=$data['configuration'];?><p><a href="<?php echo esc_url(self::url());?>">← <?php esc_html_e('Back to Automation Runs','ai-content-studio');?></a></p><section class="aics-card"><div class="aics-card-header"><h2><?php echo esc_html(sprintf(__('Run #%d','ai-content-studio'),$r['id']));?></h2></div><div class="aics-card-body"><dl class="aics-run-details"><?php self::item('Automation',$data['profile_name']);self::item('Run UUID',substr($r['run_uuid'],0,12).'…');self::item('Trigger',$i->trigger_label($r['trigger_type']));self::item('Status',$i->status_label($r['status']));self::item('Current Step',$i->step_label($r['current_step']));self::item('Created',self::date($r['created_at']));self::item('Started',self::date($r['started_at']));self::item('Last Updated',self::date($r['updated_at']));self::item('Completed',self::date($r['completed_at']));self::item('Attempts',$r['attempt_count'].' / '.$r['max_attempts']);self::item('Next Retry',self::retry($r['next_retry_at']));self::item('Configuration Source','snapshot'===$data['configuration_source']?'Saved Run Configuration':'Legacy Profile Fallback');self::item('Profile Lock',$r['active_profile_key']?'Active':'Not active');?></dl><?php if('profile_fallback'===$data['configuration_source']):?><div class="notice notice-info inline"><p><?php esc_html_e('This legacy run did not store an immutable configuration snapshot. Current profile settings may not represent its original configuration.','ai-content-studio');?></p></div><?php endif;?></div></section><?php self::config($c);self::ideas($data['ideas'],$i);self::articles($data['articles'],$i);?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Error Information','ai-content-studio');?></h2></div><div class="aics-card-body"><p><?php echo esc_html($i->error_label($r['last_error_code']));?></p><?php if($r['last_error_code']):?><code><?php echo esc_html($r['last_error_code']);?></code><?php endif;?><p><?php esc_html_e('Detailed step-event history is not stored in this version.','ai-content-studio');?></p></div></section><?php }
	private static function cards(array $c):void{?><div class="aics-dashboard-cards"><?php foreach(array('active'=>'Active Runs','retrying'=>'Retrying Runs','failed'=>'Failed Runs','completed'=>'Completed Runs','needs_attention'=>'Needs Attention') as $k=>$l):?><div class="aics-dashboard-card"><span><?php echo esc_html__($l,'ai-content-studio');?></span><strong><?php echo esc_html(number_format_i18n($c[$k]));?></strong></div><?php endforeach;?></div><?php }
	private static function filters($view,$status,$step,$trigger,$profile,$range,$profiles):void{?><form class="aics-run-filters" method="get"><input type="hidden" name="page" value="<?php echo esc_attr(self::SLUG);?>"><input type="hidden" name="run_view" value="<?php echo esc_attr($view);?>"><?php self::select('status','Status',$status,array(''=>'All statuses','queued'=>'Queued','running'=>'Running','retrying'=>'Retrying','completed'=>'Completed','failed'=>'Failed','cancelled'=>'Cancelled'));self::select('step','Workflow Step',$step,array(''=>'All steps','pending'=>'Pending','generate_ideas'=>'Generating Ideas','evaluate_ideas'=>'Evaluating Ideas','queue_idea'=>'Preparing Articles','generate_article'=>'Generating Articles','waiting_idea_approval'=>'Waiting for Idea Approval','waiting_article_approval'=>'Waiting for Article Approval','create_post'=>'Creating Posts','waiting_publish_approval'=>'Waiting for Publishing Approval','schedule_post'=>'Scheduling Posts','publish_post'=>'Publishing Posts','finalize'=>'Finalizing','complete'=>'Complete'));self::select('trigger','Trigger Type',$trigger,array(''=>'All triggers','scheduled'=>'Scheduled','manual'=>'Manual','retry'=>'Retry','system'=>'System'));$po=array(''=>'All profiles');foreach($profiles as $p){$po[$p['id']]=$p['profile_name'];}self::select('profile_id','Automation Profile',(string)$profile,$po);self::select('date_range','Date Range',$range,array(''=>'All Time','7'=>'Last 7 Days','30'=>'Last 30 Days','90'=>'Last 90 Days'));?><button class="button"><?php esc_html_e('Filter','ai-content-studio');?></button><a class="button" href="<?php echo esc_url(self::url(array('run_view'=>$view)));?>"><?php esc_html_e('Reset','ai-content-studio');?></a></form><?php }
	private static function config(array $c):void{$content=$c['content_settings']??array();$rules=$c['workflow_rules']??array();$pub=$c['publishing_settings']??array();$schedule=$c['schedule_settings']??array();$author=get_userdata(absint($pub['author_id']??0));$category=get_term(absint($pub['category_id']??0),'category');?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Configuration Used','ai-content-studio');?></h2></div><div class="aics-card-body"><dl class="aics-run-details"><?php self::item('Mode',ucfirst($c['mode']??'Unknown'));self::item('Ideas per cycle',$content['ideas_per_cycle']??'—');self::item('Selected ideas',$content['selected_ideas_per_cycle']??'—');self::item('Article length',ucfirst($content['article_length']??'Unknown'));self::item('Idea approval',!empty($rules['require_idea_approval'])?'Required':'Not required');self::item('Article approval',!empty($rules['require_article_approval'])?'Required':'Not required');self::item('Publishing approval',!empty($rules['require_publish_approval'])?'Required':'Not required');self::item('Publishing mode',ucfirst($pub['publishing_mode']??'Unknown'));self::item('Schedule frequency',ucfirst($schedule['frequency']??'Unknown'));self::item('Publishing time',$schedule['publish_time']??'—');self::item('Author',$author instanceof WP_User?$author->display_name:'Unavailable');self::item('Category',$category instanceof WP_Term?$category->name:'Unavailable');?></dl></div></section><?php }
	private static function ideas(array $ideas,AICS_Automation_Run_Inspector $i):void{?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Ideas','ai-content-studio');?></h2></div><div class="aics-card-body aics-table-wrap"><table class="widefat striped"><thead><tr><th>Idea</th><th>Score</th><th>Status</th><th>Approval</th><th>Rejection Reason</th><th>Created</th><th>Updated</th></tr></thead><tbody><?php foreach($ideas as $x):?><tr><td><strong><?php echo esc_html($x['title']);?></strong><br><?php echo esc_html(wp_html_excerpt($x['summary'],100,'…'));?></td><td><?php echo esc_html(number_format_i18n($x['score'],2));?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$x['status'])));?></td><td><?php echo esc_html($x['approved_by']>0?'Administrator-approved':($x['approved_at']?'Automatic':'Not applicable'));?></td><td><?php echo esc_html($x['rejection_code']?ucwords(str_replace('_',' ',$x['rejection_code'])):'—');?></td><td><?php echo esc_html(self::date($x['created_at']));?></td><td><?php echo esc_html(self::date($x['updated_at']));?></td></tr><?php endforeach;?></tbody></table></div></section><?php }
	private static function articles(array $articles,AICS_Automation_Run_Inspector $i):void{?><section class="aics-card"><div class="aics-card-header"><h2><?php esc_html_e('Articles and WordPress Posts','ai-content-studio');?></h2></div><div class="aics-card-body aics-table-wrap"><table class="widefat striped"><thead><tr><th>Article</th><th>Status</th><th>Words</th><th>Attempts</th><th>WordPress Post</th><th>Planned</th><th>Last Error</th><th>Updated</th></tr></thead><tbody><?php foreach($articles as $a):$p=$a['post_info'];?><tr><td><?php echo esc_html($a['title']?:__('Title not generated','ai-content-studio'));?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$a['status'])));?></td><td><?php echo esc_html(number_format_i18n($a['word_count']));?></td><td><?php echo esc_html(number_format_i18n($a['generation_attempts']));?></td><td><?php if($p['missing']):esc_html_e('Missing WordPress Post','ai-content-studio');elseif(!$p['expected']):esc_html_e('Not Created','ai-content-studio');else:?>#<?php echo esc_html($p['id']);?> · <?php echo esc_html($p['status']);?><?php if(current_user_can('edit_post',$p['id'])):?><br><a href="<?php echo esc_url(get_edit_post_link($p['id'],'raw'));?>"><?php esc_html_e('Edit in WordPress','ai-content-studio');?></a><?php endif;endif;?></td><td><?php echo esc_html(self::date($a['planned_publish_at']));?></td><td><?php echo esc_html($i->error_label($a['last_error_code']));?></td><td><?php echo esc_html(self::date($a['updated_at']));?></td></tr><?php endforeach;?></tbody></table></div></section><?php }
	private static function select($name,$label,$value,array $options):void{?><label><span><?php echo esc_html__($label,'ai-content-studio');?></span><select name="<?php echo esc_attr($name);?>"><?php foreach($options as $v=>$l):?><option value="<?php echo esc_attr($v);?>" <?php selected((string)$value,(string)$v);?>><?php echo esc_html__($l,'ai-content-studio');?></option><?php endforeach;?></select></label><?php }
	private static function item($label,$value):void{?><div><dt><?php echo esc_html__($label,'ai-content-studio');?></dt><dd><?php echo esc_html((string)$value);?></dd></div><?php }private static function allowed($key,array $allowed):string{$v=isset($_GET[$key])?sanitize_key(wp_unslash($_GET[$key])):'';return in_array($v,$allowed,true)?$v:'';}private static function date($utc):string{return is_string($utc)&&$utc?get_date_from_gmt($utc,get_option('date_format').' '.get_option('time_format')):'—';}private static function retry($utc):string{return !$utc?'—':($utc<=current_time('mysql',true)?__('Ready for retry','ai-content-studio'):self::date($utc));}private static function url(array $args=array()):string{return add_query_arg(array_merge(array('page'=>self::SLUG),$args),admin_url('admin.php'));}private static function pagination($total,$page):void{$pages=(int)ceil($total/self::PER_PAGE);if($pages<2)return;echo wp_kses_post(paginate_links(array('base'=>add_query_arg('paged','%#%'),'format'=>'','current'=>$page,'total'=>$pages,'type'=>'list')));}
}
